import { PagingOptions } from '../contracts/types';
import { ApiBase } from './ApiBase';
import { idToString } from './parser';
import {
    LicenseEntity,
    PaymentEntity,
    UserBillingEntity,
    UserEntity,
    UserFilterOptions,
    FSId,
    UserSubscriptionFilterOptions,
    UserLicenseFilterOptions,
    UserPaymentFilterOptions,
    BillingUpdatePayload,
    UserSubscriptionWithDiscounts,
    SubscriptionDiscountEntity,
    UserCustomerPortalResult,
} from './types';

const USER_FIELDS = 'email,first,last,picture,is_verified,id,created,updated,is_marketing_allowed';

export class User extends ApiBase<UserEntity, UserFilterOptions> {
    async retrieve(userId: FSId) {
        const userResponse = await this.client.GET(`/products/{product_id}/users/{user_id}.json`, {
            params: {
                path: {
                    product_id: this.productId,
                    user_id: this.getIdForPath(userId),
                },
                query: {
                    fields: USER_FIELDS,
                },
            },
        });

        if (userResponse.response.status !== 200 || !userResponse.data || !userResponse.data.id) {
            return null;
        }

        return userResponse.data;
    }

    async retrieveMany(filter?: UserFilterOptions, pagination?: PagingOptions) {
        const response = await this.client.GET(`/products/{product_id}/users.json`, {
            params: {
                path: {
                    product_id: this.productId,
                },
                query: {
                    ...this.getPagingParams(pagination),
                    ...(filter ?? {}),
                    fields: USER_FIELDS,
                },
            },
        });

        if (response.response.status !== 200 || !response.data || !Array.isArray(response.data.users)) {
            return [];
        }

        return response.data.users;
    }

    async retrieveByEmail(email: string): Promise<UserEntity | null> {
        const response = await this.client.GET(`/products/{product_id}/users.json`, {
            params: {
                path: {
                    product_id: this.productId,
                },
                query: {
                    email,
                },
            },
        });

        if (!this.isGoodResponse(response.response) || !Array.isArray(response.data?.users)) {
            return null;
        }

        return response.data.users?.[0] ?? null;
    }

    async retrieveBilling(userId: FSId): Promise<UserBillingEntity | null> {
        const billingResponse = await this.client.GET(`/products/{product_id}/users/{user_id}/billing.json`, {
            params: {
                path: {
                    product_id: this.productId,
                    user_id: this.getIdForPath(userId),
                },
            },
        });

        if (billingResponse.response.status !== 200 || !billingResponse.data || !billingResponse.data) {
            return null;
        }

        return billingResponse.data;
    }

    async retrieveSubscriptions(
        userId: FSId,
        filters?: UserSubscriptionFilterOptions,
        pagination?: PagingOptions
    ): Promise<UserSubscriptionWithDiscounts[]> {
        const result = await this.client.GET(`/products/{product_id}/users/{user_id}/subscriptions.json`, {
            params: {
                path: {
                    product_id: this.productId,
                    user_id: this.getIdForPath(userId),
                },
                query: {
                    ...(filters ?? {}),
                    ...this.getPagingParams(pagination),
                },
            },
        });

        if (!this.isGoodResponse(result.response) || !result.data || !Array.isArray(result.data.subscriptions)) {
            return [];
        }

        const discountsMap: Map<string, SubscriptionDiscountEntity[]> = new Map();

        if (result.data.discounts) {
            Object.entries(result.data.discounts).forEach(([subscriptionId, discounts]) => {
                discountsMap.set(idToString(subscriptionId), discounts);
            });
        }

        return result.data.subscriptions.map((subscription) => ({
            ...subscription,
            discounts: discountsMap.get(idToString(subscription.id!)) || [],
        }));
    }

    async retrieveLicenses(
        userId: FSId,
        filters?: UserLicenseFilterOptions,
        pagination?: PagingOptions
    ): Promise<LicenseEntity[]> {
        const response = await this.client.GET(`/products/{product_id}/users/{user_id}/licenses.json`, {
            params: {
                path: {
                    product_id: this.productId,
                    user_id: this.getIdForPath(userId),
                },
                query: {
                    ...(filters ?? {}),
                    ...this.getPagingParams(pagination),
                },
            },
        });

        if (response.response.status !== 200 || !response.data || !Array.isArray(response.data.licenses)) {
            return [];
        }

        return response.data.licenses;
    }

    async retrievePayments(
        userId: FSId,
        filters?: UserPaymentFilterOptions,
        pagination?: PagingOptions
    ): Promise<PaymentEntity[]> {
        const response = await this.client.GET(`/products/{product_id}/users/{user_id}/payments.json`, {
            params: {
                path: {
                    product_id: this.productId,
                    user_id: this.getIdForPath(userId),
                },
                query: {
                    ...(filters ?? {}),
                    ...this.getPagingParams(pagination),
                },
            },
        });

        if (response.response.status !== 200 || !response.data || !Array.isArray(response.data.payments)) {
            return [];
        }

        return response.data.payments;
    }

    async updateBilling(userId: FSId, payload: BillingUpdatePayload): Promise<UserBillingEntity | null> {
        const response = await this.client.PUT(`/products/{product_id}/users/{user_id}/billing.json`, {
            params: {
                path: {
                    product_id: this.productId,
                    user_id: this.getIdForPath(userId),
                },
            },
            body: payload,
        });

        if (!this.isGoodResponse(response.response) || !response.data || !response.data) {
            return null;
        }

        return response.data;
    }

    async retrieveHostedCustomerPortal(userId: FSId): Promise<UserCustomerPortalResult | null> {
        const response = await this.client.POST(`/products/{product_id}/portal/login.json`, {
            params: {
                path: { product_id: this.productId },
            },
            body: {
                id: idToString(userId),
            },
        });

        if (!this.isGoodResponse(response.response) || !response.data) {
            return null;
        }

        return response.data;
    }

    async retrieveHostedCustomerPortalByEmail(email: string): Promise<UserCustomerPortalResult | null> {
        const response = await this.client.POST(`/products/{product_id}/portal/login.json`, {
            params: {
                path: { product_id: this.productId },
            },
            body: {
                email,
            },
        });

        if (!this.isGoodResponse(response.response) || !response.data) {
            return null;
        }

        return response.data;
    }

    async retrieveInvoice(userId: FSId, paymentId: FSId): Promise<Blob | null> {
        const response = await this.client.GET(
            `/products/{product_id}/users/{user_id}/payments/{payment_id}/invoice.pdf`,
            {
                params: {
                    path: {
                        product_id: this.productId,
                        user_id: this.getIdForPath(userId),
                        payment_id: this.getIdForPath(paymentId),
                    },
                },
                parseAs: 'blob',
            }
        );

        if (!this.isGoodResponse(response.response) || !response.data) {
            return null;
        }

        return response.data;
    }
}
